use serde_json::json;
use tracework_client::{Client,Source,exact_uint64,Result};
fn main()->Result<()>{let base=std::env::var("TRACEWORK_URL").unwrap_or("http://127.0.0.1:8080".into());let token=std::env::var("TRACEWORK_TOKEN").unwrap_or_default();let c=Client::new(&base,&token)?;let p=c.create_project("Rust SDK conformance")?;let pid=p["id"].as_str().ok_or("Project ID missing")?;let src=c.define_source(pid,&json!({"name":"Counter","clock_domain":"rust-clock","stale_ms":3000,"events":[{"name":"sample","version":1,"fields":[{"name":"count","type":"uint64","unit":"cycles"}]}]}))?;let ss=c.start_recording(pid,"Rust native exact evidence")?;let sid=ss["id"].as_str().ok_or("Session missing")?;let mut producer=Source::new(&c,pid,src["id"].as_str().ok_or("Source missing")?,src["events"][0]["id"].as_str().ok_or("Schema missing")?,1,"rust-clock",&format!("rust_fixture_{}",std::process::id()))?;producer.recording=Some(sid.into());let mut values=serde_json::Map::new();values.insert("count".into(),exact_uint64(u64::MAX));producer.emit(values,1790612345678901234,false)?;c.stop_recording(sid)?;c.events(sid,|event|{if event["values"]["count"]!=json!("18446744073709551615"){return Err("Precision changed".into());}Ok(())})?;println!("{}",json!({"project_id":pid,"session_id":sid}));Ok(())}
